function titleCaseName(v){
  try{
    if(!v) return v;
    const text = String(v).trim();
    if(!text) return text;
    return text.split(/\s+/).map(word=>word.charAt(0).toUpperCase()+word.slice(1).toLowerCase()).join(" ");
  }catch{return v}
}
let state=loadState(),config,curriculum,diagnosticData,moduleReviewData={},vocabulary=[],lessonMap=new Map(),lessonData=null,diagnosticSession=null,lessonSession=null,moduleReviewSession=null,repeatSession=null,wordGameSession=null,account={status:"loading"},accountChildren=[],pendingMigrationChild=null;
