async function json(url){const r=await fetch(url);if(!r.ok)throw new Error(`Yüklenemedi: ${url}`);return r.json()}
async function loadData(){config=await json("data/app-config.json");let rawVocabulary;[curriculum,diagnosticData,rawVocabulary]=await Promise.all([json(config.curriculumUrl),json(config.diagnosticUrl),json(config.vocabularyUrl)]);const reviewUrls=config.moduleReviews||{"module-1":config.reviewUrl};const reviewEntries=await Promise.all(Object.entries(reviewUrls).map(async([id,url])=>[id,await json(url)]));moduleReviewData=Object.fromEntries(reviewEntries);vocabulary=normalizeVocabulary(rawVocabulary);const rows=flattenLessons(curriculum).filter(x=>x.status==="published");const lessons=await Promise.all(rows.map(x=>json(x.file)));for(const l of lessons){if(lessonMap.has(l.id))throw new Error(`Tekrarlanan ders: ${l.id}`);lessonMap.set(l.id,l)}for(const row of rows)if(!lessonMap.has(row.id))throw new Error(`Curriculum-dosya uyuşmazlığı: ${row.id}`)}
function chooseLesson(id){const row=flattenLessons(curriculum).find(x=>x.id===id);if(!row||!lessonMap.has(id)||!isUnlocked(row,state,curriculum))return false;lessonData=lessonMap.get(id);state.selectedLessonId=id;saveState(state);return true}
function setActiveRoute(r){updateProfileMenu();document.querySelectorAll("header [data-route]").forEach(b=>{const gameActive=r==="games"||r.startsWith("game/");const active=b.dataset.route==="games"&&(gameActive||r==="stories"||r.startsWith("story/"));b.classList.toggle("active",active);b.setAttribute("aria-current",active?"page":"false")})}
function route(){state=loadState();document.body.dataset.theme=state.settings.theme;const r=getRoute();trackRouteView(r);if(!r.startsWith("story/"))resetStoryRuntime();setActiveRoute(r);if(r==="games")return gamesHub();if(r==="game/football")return footballGameView(app,{state,vocabulary,updateState});if(r==="game/volleyball")return volleyballGameView(app,{state,vocabulary,updateState});if(account.status==="loading")return loadingAccount();if(r==="login")return loginPage();if(r==="signup")return signupPage();if(r==="stories"||r.startsWith("story/"))return storyRoute(r);if(account.status!=="signed-in")return authLanding();if(r==="account")return accountHome();if(r==="profiles")return profileSelector();if(r==="teacher")return teacherPage();const studentRoutes=["home","diagnostic","diagnostic-result","final-result","vocabulary","word-game/hard","word-game/tournament","module-review","module-review-result","review-mistakes","lesson","parent"];const isStudentRoute=studentRoutes.includes(r)||r.startsWith("lesson/")||r.startsWith("worksheet/")||r.startsWith("parent/")||r.startsWith("module-review/")||r.startsWith("module-review-result/");if(isStudentRoute&&!getActiveStudentId(account.user.id)){if((account.profile?.account_type||"parent")==="student"&&accountChildren[0])return selectChild(accountChildren[0],false,r);return profileSelector()}if(!state.onboardingComplete&&r==="home")return welcome();if(r==="diagnostic")return diagnostic();if(r==="diagnostic-result")return diagnosticResult();if(r==="final-result")return finalResult();if(r==="vocabulary")return vocabularyVault();if(r==="word-game/hard")return wordGame("hard");if(r==="word-game/tournament")return wordGame("tournament");if(r==="module-review")return moduleReview("module-1");if(r==="module-review-result")return moduleReviewResult("module-1");if(r.startsWith("module-review/"))return moduleReview(r.split("/")[1]);if(r.startsWith("module-review-result/"))return moduleReviewResult(r.split("/")[1]);if(r==="review-mistakes")return repeatMistakes();if(r.startsWith("worksheet/")){lessonData=lessonMap.get(r.split("/")[1]);return worksheetView()}if(r.startsWith("lesson/")){if(!chooseLesson(r.split("/")[1]))return home();lessonSession=null;return lesson()}if(r==="lesson"){const id=state.selectedLessonId||nextAvailableLesson(curriculum,state)?.id;if(!chooseLesson(id))return home();return lesson()}if(r.startsWith("parent/")){lessonData=lessonMap.get(r.split("/")[1])||lessonData;return parent()}if(r==="parent"){lessonData=lessonMap.get(state.selectedLessonId)||lessonMap.get(nextAvailableLesson(curriculum,state)?.id)||lessonMap.values().next().value;return parent()}home()}
async function storyRoute(r){const signedIn=account.status==="signed-in",acctType=signedIn?(account.profile?.account_type||"student"):"student";if(signedIn&&["student","parent","both"].includes(acctType)&&!getActiveStudentId(account.user.id)){if(acctType==="student"&&accountChildren[0])return selectChild(accountChildren[0],false,r);return profileSelector()}if(signedIn&&acctType==="teacher"){const status=await resolveTeacherStatus(account,teacherRepo).catch(()=>({approval_status:"pending"}));if(!canUseTeacherTools(status)){app.innerHTML=teacherStatusView(status,{approved:false});bindRoutes();return}}try{if(r==="stories")return await storiesListView(app,{state,account,accountChildren});return await storyDetailView(app,{state,account,accountChildren})}catch(err){app.innerHTML=`<section class="card"><p class="eyebrow">POMA HİKÂYELERİ</p><h1>Hikâye yüklenemedi.</h1><p>${esc(err.message||"Beklenmeyen hata")}</p><button class="button secondary" data-route="games">Eğlence</button></section>`;bindRoutes()}}
