function signupPage(){app.innerHTML=signupView();bindRoutes();app.querySelector("form")?.addEventListener("submit",async e=>{e.preventDefault();const f=new FormData(e.currentTarget),couponCode=String(f.get("couponCode")||"").trim().toUpperCase();trackEvent("signup_form_submitted",{source:"signup"});try{account=await signUp({email:f.get("email"),password:f.get("password"),displayName:f.get("displayName"),accountType:f.get("accountType"),couponCode});trackEvent("signup_completed",{source:"signup",status:"success"});if(couponCode){try{sessionStorage.setItem("pomaAcademy.signup.lastCoupon",couponCode);sessionStorage.removeItem("pomaAcademy.signup.coupon")}catch{}}accountChildren=await loadChildrenForSession(account).catch(()=>[]);showToast("Hesap oluşturuldu.");navigate((account.profile?.account_type||"parent")==="teacher"?"teacher":"profiles")}catch(err){showToast(err.message||"Hesap oluşturulamadı.")}})}
