function diagnosticResult(){const r=state.diagnostic;if(!r)return navigate("diagnostic");const rec=resolveRecommendation(curriculum,r.band.startLesson,state),available=rec.available,answeredCount=r.earlyRecommendation?4:diagnosticData.questions.length,wrong=diagnosticData.questions.slice(0,answeredCount).map((q,i)=>({q,a:r.answers[i]})).filter(x=>x.a!==x.q.correctIndex);app.innerHTML=`<section><div class="page-head"><div><p class="eyebrow">UYGULAMA İÇİ BAŞLANGIÇ SEVİYESİ TAHMİNİ</p><h1>${esc(r.band.label)}</h1><p class="lead">Tek soruluk alanlar kesin hâkimiyet ölçümü değildir; geniş beceri grupları yol gösterir.</p></div></div><article class="card results-score"><div class="score-ring" style="--score:${r.percent}"><strong>${r.score}/${r.total||25}</strong></div><div><h2>Önerilen başlangıç</h2><p>${esc(available?.title||"Ders hazırlanıyor")}</p>${r.earlyRecommendation?`<p>İstersen ana ekrandan 25 soruluk tam seviye testini daha sonra yine çözebilirsin.</p>`:""}${rec.fallback?`<p>Hedef: ${esc(rec.target.title)}. Henüz yayımlanmadığı için en yakın mevcut önceki ders önerildi.</p>`:""}${available?`<button class="button primary" data-route="lesson/${available.id}">Dersi aç →</button>`:""}</div></article><div class="analysis-grid grid"><article class="card"><h2>Geniş beceri grupları</h2>${r.skillGroups.map(g=>`<div class="analysis-row"><span>${esc(g.label)}</span><strong>${g.correct}/${g.total}</strong><div class="progress"><span style="width:${g.percent}%"></span></div></div>`).join("")}</article><article class="card"><h2>Ayrıntılı soru sonuçları</h2>${wrong.map(({q,a})=>`<details><summary>${esc(q.prompt)}</summary><p class="feedback incorrect">${esc(q.explanationsTr[a])}</p><p>Doğru: ${esc(q.options[q.correctIndex])}</p></details>`).join("")||"Tüm cevaplar doğru."}</article></div></section>`;bindRoutes()}
function lesson(){const saved=state.lessonProgress[lessonData.id]||{};if(!lessonSession)lessonSession=createLessonSession(lessonData,saved.completed?{}:saved);const s=lessonSession,screen=s.lesson.screens[s.index],answer=s.answers[screen.id]||(s.answers[screen.id]={}),stats=lessonStats(s);app.innerHTML=`<section class="lesson-shell"><div class="lesson-head"><button class="button secondary" data-route="home">← Ana ekran</button><div class="progress"><span style="width:${(s.index+1)/s.lesson.screens.length*100}%"></span></div><span>${s.index+1}/${s.lesson.screens.length}</span></div><article class="card lesson-stage">${renderScreen(screen,answer)}</article><div class="button-row"><button class="button secondary" data-action="back" ${s.index===0?"disabled":""}>← Geri</button><button class="button primary" data-action="next" ${isInteractive(screen.type)&&!answer.completed?"disabled":""}>${s.index===s.lesson.screens.length-1?"Dersi tamamla":"Devam →"}</button></div><p>Etkinlikler ${stats.completed}/${stats.total} · ${stats.points} puan</p></section>`;bindRoutes();bindActivity(app.querySelector(".lesson-stage"),screen,answer,()=>{saveDraft();lesson()},state.settings.muted);app.querySelector("[data-action='back']")?.addEventListener("click",()=>{s.index--;saveDraft();lesson()});app.querySelector("[data-action='next']")?.addEventListener("click",()=>{if(isInteractive(screen.type)&&!answer.completed)return;if(s.index<s.lesson.screens.length-1){s.index++;saveDraft();lesson()}else completeLesson()})}
function reviewIds(old={}){return [...new Set([...(old.reviewScreens||[]),...Object.entries(lessonSession.answers).filter(([,a])=>(a.wrongCount||0)>0||(a.wrongAttempts||0)>0).map(([id])=>id)])]}
function syncVocabularyFromAnswers(x){const byId=new Map(vocabulary.map(w=>[w.id,w]));for(const a of Object.values(lessonSession?.answers||{})){if(!a.vocabResults)continue;for(const [wordId,ok] of Object.entries(a.vocabResults)){const word=byId.get(wordId),key=`vocabSaved_${wordId}`;if(word&&a[key]!==ok){recordWordAnswer(x,word,ok);a[key]=ok}}}return x}
function saveDraft(){const st=lessonStats(lessonSession);state=updateState(x=>{syncVocabularyFromAnswers(x);const old=x.lessonProgress[lessonData.id]||{};x.lessonProgress[lessonData.id]={...old,currentScreen:lessonSession.index,answers:lessonSession.answers,startedAt:lessonSession.startedAt,lastRunPoints:st.points,lastRunPercent:st.percent,reviewScreens:reviewIds(old)};return markStudyDay(x)})}
function completeLesson(){const s=lessonStats(lessonSession),finalAnswers=structuredClone(lessonSession.answers);state=updateState(x=>{syncVocabularyFromAnswers(x);const old=x.lessonProgress[lessonData.id]||{},badge=lessonData.id==="000-quick-start"?"İlk Adım Rozeti":old.badge,result={completed:true,completedAt:new Date().toISOString(),currentScreen:lessonData.screens.length-1,points:s.points+20,percent:s.percent,stars:s.stars,answers:lessonSession.answers,reviewScreens:reviewIds(old),badge};x.lessonProgress[lessonData.id]=mergeBestResult(old,result);const done=Object.values(x.lessonProgress).filter(p=>p.completed);x.totals={completedLessons:done.length,points:done.reduce((n,p)=>n+(p.bestPoints||0),0),stars:done.reduce((n,p)=>n+(p.bestStars||0),0)};if(lessonData.id==="065-final-exam")x.finalExamResult=buildFinalExamResult(x,finalAnswers);return markStudyDay(x)});trackEvent("learning_completed",{content_type:"lesson",content_id:lessonData.id,status:"completed"});lessonSession=null;showToast(`${lessonData.id==="000-quick-start"?"İlk Adım Rozeti · ":""}${s.stars} yıldız · ${s.points+20} puan`);navigate(lessonData.id==="065-final-exam"?"final-result":"home")}
function buildFinalExamResult(x,answers){const rounds=lessonData.screens.find(s=>s.id==="s14b")?.content?.rounds||[],byTopic=new Map();for(const r of rounds){const key=r.topicTag||r.section||"general",row=byTopic.get(key)||{id:key,label:r.topicLabel||r.section||key,correct:0,total:0};row.total++;const saved=Object.values(answers||{}).find(a=>Array.isArray(a.results));const hit=saved?.results?.find(z=>z.prompt===r.prompt);if(hit?.correct)row.correct++;byTopic.set(key,row)}const topics=[...byTopic.values()].map(t=>({...t,percent:Math.round(t.correct/Math.max(1,t.total)*100)})),autoTotal=rounds.length,autoCorrect=topics.reduce((n,t)=>n+t.correct,0),percent=Math.round(autoCorrect/Math.max(1,autoTotal)*100);return{completedAt:new Date().toISOString(),studentName:titleCaseName(x.profile?.name)||"Öğrenci",autoCorrect,autoTotal,percent,rubricCompleted:5,rubricTotal:5,topics,strongAreas:topics.filter(t=>t.percent>=75).map(t=>t.label),weakAreas:topics.filter(t=>t.percent<60).map(t=>t.label),recommendedLessons:topics.filter(t=>t.percent<60).map(t=>`${t.label} tekrarı`),wrongVocabulary:[],completedLessons:Object.values(x.lessonProgress||{}).filter(p=>p.completed).length,totalStars:x.totals?.stars||0,longestStreak:x.streak?.count||0}}
function finalResult(){const r=state.finalExamResult;if(!r){navigate("home");return}app.innerHTML=`<section><div class="page-head"><div><p class="eyebrow">FINAL SONUCU</p><h1>${r.autoCorrect}/${r.autoTotal} otomatik doğru · %${r.percent}</h1><p class="lead">Rubrik görevleri: ${r.rubricCompleted}/${r.rubricTotal} tamamlandı.</p></div><button class="button secondary" data-route="home">Ana ekran</button></div><div class="analysis-grid grid">${r.topics.map(t=>`<article class="card"><h2>${esc(t.label)}</h2><strong>${t.correct}/${t.total}</strong><div class="progress"><span style="width:${t.percent}%"></span></div></article>`).join("")}</div><article class="card"><h2>Güçlü alanlar</h2><p>${r.strongAreas.length?r.strongAreas.map(esc).join(", "):"Henüz belirgin güçlü alan yok; tekrar önerilir."}</p><h2>Geliştirilmesi gereken alanlar</h2><p>${r.weakAreas.length?r.weakAreas.map(esc).join(", "):"Belirgin zayıf alan yok."}</p><h2>Tekrar önerileri</h2><ul class="clean-list">${r.recommendedLessons.map(x=>`<li>${esc(x)}</li>`).join("")}</ul></article><article class="card certificate"><p class="eyebrow">BAŞARI BELGESİ</p><h1>${esc(r.studentName)}</h1><p>${new Date(r.completedAt).toLocaleDateString("tr-TR")} tarihinde Poma Academy final çalışmasını tamamladı.</p><ul class="clean-list"><li>Tamamlanan ders: ${r.completedLessons}</li><li>Final puanı: %${r.percent}</li><li>Toplam yıldız: ${r.totalStars}</li><li>En uzun seri: ${r.longestStreak} gün</li><li>Güçlü alanlar: ${r.strongAreas.join(", ")||"tekrar sonrası belirlenecek"}</li></ul><button class="button primary" data-action="print">Başarı belgesini yazdır</button></article></section>`;bindRoutes();app.querySelector("[data-action='print']")?.addEventListener("click",()=>print())}
function moduleReview(moduleId="module-1"){const data=moduleReviewData[moduleId];if(!data||!isModuleComplete(curriculum,state,moduleId))return home();const saved=state.moduleReviewDraft?.[moduleId]||(moduleId==="module-1"&&state.moduleReviewDraft?.items?state.moduleReviewDraft:null);if(!moduleReviewSession||moduleReviewSession.moduleId!==moduleId)moduleReviewSession={...createReviewSession(data,saved),moduleId};const s=moduleReviewSession,q=s.items[s.index],a=s.answers[q.id]||(s.answers[q.id]={});app.innerHTML=`<section class="lesson-shell"><div class="lesson-head"><button class="button secondary" data-route="home">← Ana ekran</button><div class="progress"><span style="width:${(s.index+1)/s.items.length*100}%"></span></div><span>${s.index+1}/${s.items.length}</span></div><p class="eyebrow">${esc(q.topicLabel)} · GENEL TEKRAR</p><article class="card lesson-stage">${renderScreen(q,a)}</article><div class="button-row"><button class="button secondary" data-action="review-back" ${s.index===0?"disabled":""}>← Geri</button><button class="button primary" data-action="review-next" ${!a.completed?"disabled":""}>${s.index===s.items.length-1?"Sınavı tamamla":"Sonraki →"}</button></div></section>`;bindRoutes();const resultRoute=moduleId==="module-1"?"module-review-result":`module-review-result/${moduleId}`;const persist=()=>{state=updateState(x=>{if(!x.moduleReviewDraft||x.moduleReviewDraft.items)x.moduleReviewDraft={};x.moduleReviewDraft[moduleId]=reviewDraft(s);return x})};bindActivity(app.querySelector(".lesson-stage"),q,a,()=>{persist();moduleReview(moduleId)},state.settings.muted);app.querySelector("[data-action='review-back']")?.addEventListener("click",()=>{s.index--;persist();moduleReview(moduleId)});app.querySelector("[data-action='review-next']")?.addEventListener("click",()=>{if(!a.completed)return;if(s.index<s.items.length-1){s.index++;persist();moduleReview(moduleId)}else{const result=analyzeModuleReview(s);state=updateState(x=>{x.moduleReviews[moduleId]=result;if(x.moduleReviewDraft?.[moduleId])delete x.moduleReviewDraft[moduleId];return x});moduleReviewSession=null;navigate(resultRoute)}})}
function moduleReviewResult(moduleId="module-1"){const r=state.moduleReviews?.[moduleId];if(!r)return navigate(moduleId==="module-1"?"module-review":`module-review/${moduleId}`);const number=moduleId.replace("module-","");app.innerHTML=`<section><div class="page-head"><div><p class="eyebrow">MODÜL ${esc(number)} GENEL TEKRAR SONUCU</p><h1>${r.correct}/${r.total} doğru ? %${r.percent}</h1></div><button class="button secondary" data-route="home">Ana ekran</button></div><div class="analysis-grid grid">${r.topics.map(t=>`<article class="card"><h2>${esc(t.label)}</h2><strong>${t.correct}/${t.total}</strong><div class="progress"><span style="width:${t.percent}%"></span></div></article>`).join("")}</div></section>`;bindRoutes()}
function repeatMistakes(){if(!repeatSession){const items=collectReviewItems(state,lessonMap);repeatSession={items,index:0,answers:{}}}if(!repeatSession.items.length||repeatSession.index>=repeatSession.items.length){repeatSession=null;showToast("Tekrar havuzu tamamlandı");navigate("home");return}const item=repeatSession.items[repeatSession.index],q=item.screen,a=repeatSession.answers[`${item.lessonId}:${item.screenId}`]||(repeatSession.answers[`${item.lessonId}:${item.screenId}`]={});app.innerHTML=`<section class="lesson-shell"><div class="lesson-head"><button class="button secondary" data-route="home">← Ana ekran</button><div class="progress"><span style="width:${(repeatSession.index+1)/repeatSession.items.length*100}%"></span></div><span>${repeatSession.index+1}/${repeatSession.items.length}</span></div><p class="eyebrow">${esc(item.lessonTitle)} · ${esc(q.title)}</p><article class="card lesson-stage">${renderScreen(q,a)}</article><div class="button-row"><button class="button primary" data-action="repeat-next" ${!a.completed?"disabled":""}>${repeatSession.index===repeatSession.items.length-1?"Tekrarı bitir":"Sonraki yanlış →"}</button></div></section>`;bindRoutes();bindActivity(app.querySelector(".lesson-stage"),q,a,()=>{if(a.completed)state=updateState(x=>removeReviewItem(x,item.lessonId,item.screenId));repeatMistakes()},state.settings.muted);app.querySelector("[data-action='repeat-next']")?.addEventListener("click",()=>{if(!a.completed)return;repeatSession.index++;repeatMistakes()})}
function vocabularyVault(){const stats=vocabularyStats(vocabulary,state),lessonTitles=new Map(flattenLessons(curriculum).map(x=>[x.id,x.title]));const section=(title,items)=>`<article class="card"><h2>${esc(title)}</h2>${items.length?`<div class="word-grid">${items.map(w=>wordCard(w)).join("")}</div>`:"<p>Şimdilik boş. Ders çözdükçe burası dolacak.</p>"}</article>`;app.innerHTML=`<section><div class="page-head"><div><p class="eyebrow">KELİME KASASI</p><h1>Bugünkü kelimeler ve akıllı tekrar</h1><p class="lead">Doğru kelimeler 1-3-7-14-30 gün aralıklarla geri gelir; zorlandıkların daha erken görünür.</p></div><button class="button secondary" data-route="home">Ana ekran</button></div><div class="stats-grid grid"><article class="card stat"><span>Öğrendim</span><strong>${stats.learned.length}</strong></article><article class="card stat"><span>Öğreniyorum</span><strong>${stats.learning.length}</strong></article><article class="card stat"><span>Zorlandıklarım</span><strong>${stats.difficult.length}</strong></article><article class="card stat"><span>Tekrar zamanı</span><strong>${stats.due.length}</strong></article></div><div class="button-row"><button class="button primary" data-route="word-game/hard">Zor Kelimeler Oyunu</button><button class="button secondary" data-route="word-game/tournament">Haftanın Kelime Turnuvası</button></div>${section("Bugünkü kelimeler",stats.due.length?stats.due:vocabulary.slice(0,8))}${section("Öğreniyorum",stats.learning.slice(0,12))}${section("Öğrendim",stats.learned.slice(0,12))}${section("Zorlandıklarım",stats.difficult.slice(0,12))}<article class="card"><h2>Derse göre kelimeler</h2>${Object.entries(stats.byLesson).map(([id,items])=>`<details><summary>${esc(lessonTitles.get(id)||id)} · ${items.length} kelime</summary><div class="word-grid">${items.map(w=>wordCard(w)).join("")}</div></details>`).join("")}</article></section>`;bindRoutes()}
function wordCard(w){return `<article class="word-card"><h3>${esc(w.word)}</h3><p><strong>${esc(w.meaningTr)}</strong></p><p>${esc(w.example)}</p><p class="muted">${esc(w.sentenceTr)}</p><small>${esc(w.sourceLessonTitle)}</small></article>`}
function wordGame(kind){if(!wordGameSession){const stats=vocabularyStats(vocabulary,state),base=kind==="hard"?(stats.difficult.length?stats.difficult:stats.due):weeklyWords(vocabulary,state);const words=base.length?base:vocabulary.slice(0,8);wordGameSession=kind==="tournament"?createTournament(words):{mode:"hard",lives:99,streak:0,bonus:0,index:0,rounds:createWordRounds(words,"hard"),answers:[]}}const s=wordGameSession,round=s.rounds[s.index];if(!round||s.lives<=0){const result={completedAt:new Date().toISOString(),score:s.answers.filter(x=>x.correct).length+s.bonus,correct:s.answers.filter(x=>x.correct).length,total:s.rounds.length,bonus:s.bonus,badge:s.mode==="tournament"?"Haftalık Kelime Rozeti":null};state=updateState(x=>{x.vocabularyTournament=result;return x});wordGameSession=null;app.innerHTML=`<section><article class="card results-score"><div class="score-ring" style="--score:${Math.round(result.correct/result.total*100)||0}"><strong>${result.correct}/${result.total}</strong></div><div><p class="eyebrow">${kind==="tournament"?"TURNUVA SONUCU":"KELİME OYUNU"}</p><h1>${result.badge||"Zor kelimeler çalışıldı"}</h1><p>Seri bonusu: ${result.bonus}</p><button class="button primary" data-route="vocabulary">Kelime Kasası'na dön</button></div></article></section>`;bindRoutes();return}app.innerHTML=`<section class="lesson-shell"><div class="lesson-head"><button class="button secondary" data-route="vocabulary">← Kelime Kasası</button><div class="progress"><span style="width:${(s.index+1)/s.rounds.length*100}%"></span></div><span>${s.index+1}/${s.rounds.length}${s.mode==="tournament"?` · ${s.lives} can`:""}</span></div><article class="card lesson-stage"><h1>${s.mode==="tournament"?"Haftanın Kelime Turnuvası":"Zor Kelimeler Oyunu"}</h1><p class="lead">${esc(round.prompt)}</p>${round.audioText?`<button class="button secondary" data-action="word-listen">🔊 Dinle</button>`:""}<div class="game-board">${round.options.map((x,i)=>`<button class="game-door" data-word-answer="${i}">${esc(x)}</button>`).join("")}</div></article></section>`;bindRoutes();app.querySelector("[data-action='word-listen']")?.addEventListener("click",()=>speak(round.audioText,state.settings.muted));app.querySelectorAll("[data-word-answer]").forEach(b=>b.onclick=()=>{const correct=Number(b.dataset.wordAnswer)===round.correctIndex;state=updateState(x=>{recordWordAnswer(x,round.word,correct);return x});s.answers.push({wordId:round.word.id,correct});if(correct){s.streak++;if(s.streak>0&&s.streak%3===0)s.bonus++}else{s.streak=0;s.lives--}s.index++;wordGame(kind)})}
function worksheetView(){if(!lessonData)return home();const w=lessonData.parentGuide.worksheet;app.innerHTML=`<section class="worksheet"><div class="page-head"><div><p class="eyebrow">ÖĞRENCİ ÇALIŞMA SAYFASI</p><h1>${esc(w.title)}</h1></div><button class="button secondary" data-route="parent/${lessonData.id}">Veli moduna dön</button></div><div class="worksheet-meta"><span>Ad Soyad: __________________________________</span><span>Tarih: __________________</span></div><p class="question-context">${esc(w.instructionTr)}</p><ol class="worksheet-questions">${w.questions.map(q=>`<li><strong>${esc(q.prompt)}</strong>${q.options?`<div>${q.options.map((x,i)=>`${String.fromCharCode(65+i)}) ${esc(x)}`).join(" &nbsp; ")}</div>`:""}<div class="writing-lines">${Array(q.spaceLines||2).fill("<span></span>").join("")}</div></li>`).join("")}</ol><div class="button-row"><button class="button primary" data-action="print-sheet">Yazdır</button></div></section>`;bindRoutes();app.querySelector("[data-action='print-sheet']").onclick=()=>print()}
function parent(){
  // Enforce account role restrictions for parent mode
  const acctType = account.profile?.account_type || "parent";
  if(acctType === "student"){
    // students must not access parent mode
    navigate("home");
    return;
  }
  // parents/both must have an active student selected
  if(["parent","both"].includes(acctType) && !getActiveStudentId(account.user.id)){
    navigate("profiles");
    return;
  }
  app.innerHTML=parentView(state,lessonData,curriculum,lessonMap,vocabulary);bindRoutes();app.querySelector("[data-action='print']")?.addEventListener("click",()=>print());app.querySelector("[data-action='share-parent-report']")?.addEventListener("click",async()=>{const text=parentReportShareText(buildParentReport(state,vocabulary));if(navigator.share){await navigator.share({title:"Poma Academy Gelişim Özeti",text}).catch(()=>{})}else{open(`https://wa.me/?text=${encodeURIComponent(text)}`,"_blank","noopener,noreferrer")}});app.querySelector("[data-action='reset']")?.addEventListener("click",()=>{if(confirm("Tüm ilerleme silinsin mi?")){resetState();state=loadState();navigate("home");route()}})
}
