function updateProfileMenu(){const menu=document.querySelector("[data-profile-menu]"),name=document.querySelector("[data-profile-name]");if(!menu||!name)return;const signedIn=account.status==="signed-in";menu.hidden=!signedIn;if(!signedIn)return;const activeId=getActiveStudentId(account.user?.id),child=accountChildren.find(c=>String(c.id)===String(activeId));name.textContent=titleCaseName(child?.name||state.profile?.name||account.profile?.display_name||"Profil")}
