function openParentFromProfile(){const type=account.profile?.account_type||"student";closeProfileMenu();if(["parent","both"].includes(type)){if(!getActiveStudentId(account.user?.id))return navigate("profiles");return navigate("parent")}showToast("Veli modu için veli yetkili hesaba geçmelisin.");navigate("account")}
function setupProfileMenu(){const menu=document.querySelector("[data-profile-menu]"),toggle=document.querySelector("[data-action='profile-menu-toggle']"),dropdown=document.querySelector("[data-profile-dropdown]");if(!menu||!toggle||!dropdown)return;toggle.onclick=e=>{e.stopPropagation();dropdown.hidden=!dropdown.hidden;toggle.setAttribute("aria-expanded",String(!dropdown.hidden))};menu.querySelector("[data-action='profile-switch']").onclick=()=>{clearAccountSelection(account.user?.id);pendingMigrationChild=null;closeProfileMenu();navigate("profiles")};menu.querySelector("[data-action='profile-parent']").onclick=openParentFromProfile;menu.querySelector("[data-action='profile-logout']").onclick=logoutAccount;document.addEventListener("click",e=>{if(!menu.contains(e.target))closeProfileMenu()});document.addEventListener("keydown",e=>{if(e.key==="Escape")closeProfileMenu()});updateProfileMenu()}
function showToast(m){const t=document.querySelector("#toast");t.textContent=m;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),2500)}
function globalSetup(){document.querySelectorAll("header [data-route]").forEach(b=>b.onclick=()=>navigate(b.dataset.route));setActiveRoute(getRoute());document.querySelector("#theme-toggle").onclick=()=>{state=updateState(x=>{x.settings.theme=x.settings.theme==="light"?"dark":"light";return x});document.body.dataset.theme=state.settings.theme};const soundButton=document.querySelector("#sound-toggle"),syncSoundButton=()=>{if(!soundButton)return;soundButton.setAttribute("aria-pressed",String(Boolean(state.settings.muted)));soundButton.childNodes[0].nodeValue=state.settings.muted?"🔇":"🔊"};syncSoundButton();soundButton.onclick=()=>{state=updateState(x=>{x.settings.muted=!x.settings.muted;return x});syncSoundButton();window.dispatchEvent(new CustomEvent("beyza-sound-change",{detail:{muted:state.settings.muted}}));if(state.settings.muted)stopAudio()};document.querySelector("#fullscreen-toggle").onclick=toggleFullscreen;setupKeyboardActivation();window.addEventListener("poma-state-saved",()=>scheduleStudentSync(syncEngine));window.addEventListener("online",()=>syncEngine.flushQueue().catch(()=>{}));document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="hidden")scheduleStudentSync(syncEngine,100)});let refreshing=false;navigator.serviceWorker?.addEventListener("controllerchange",()=>{if(refreshing)return;refreshing=true;showToast("Yeni surum yuklendi.");setTimeout(()=>location.reload(),450)});
  // parent mode button visibility and behavior
  try{
    const pb = document.querySelector('.parent-button');
    if(pb){
      const acctType = account.profile?.account_type || 'parent';
      const hasActive = !!(account && account.user && getActiveStudentId(account.user.id));
      if(acctType === 'student') pb.style.display = 'none';
      else if(['parent','both'].includes(acctType)) pb.style.display = hasActive? 'inline-block' : 'none';
      else pb.style.display = 'none';
      pb.onclick = ()=>{
        const t = account.profile?.account_type || 'parent';
        if(t === 'student') return navigate('home');
        if(['parent','both'].includes(t) && !getActiveStudentId(account.user.id)) return navigate('profiles');
        return navigate('parent');
      }
    }
  }catch(e){}
  onRouteChange(route)}
